        || parsed.rawSpec === ''
        || parsed.rawSpec === '*'
      if (!isNameOnly && !isExactVersionDisjunction(parsed.fetchSpec)) {
        log.warn(
          'install-scripts',
          `${sourceLabel}: ignoring "${key}" — semver ranges (^, ~, >=, <) are not allowed; ` +
          'use exact versions joined by "||" instead'
